#[AutoconfigureTag(\'app.payment_gateway\')]
interface PaymentGatewayInterface { ... }

class PaymentManager {
    public function __construct(
        #[AutowireIterator(\'app.payment_gateway\')]
        private iterable $gateways
    ) {}
}
