      'solution_code' => '<?php

declare(strict_types=1);

namespace App\\DevOps\\CiCd;

use Closure;
use InvalidArgumentException;
use Throwable;

class CiPipelineRunner
{
    /**
     * @var array<string, Closure>
     */
    private array $steps = [];

    public function addStep(string $name, Closure $check): void
    {
        $clean = trim($name);
        if ($clean === \'\') {
            throw new InvalidArgumentException(\'El nombre del paso no puede estar vacio.\');
        }

        $this->steps[$clean] = $check;
    }

    public function run(): array
    {
        $total = count($this->steps);
        $executed = 0;

        foreach ($this->steps as $name => $check) {
            $executed++;
            try {
                $result = $check();
                if ($result === false) {
                    return [
                        \'passed\' => false,
                        \'total_steps\' => $total,
                        \'executed_steps\' => $executed,
                        \'failed_step\' => $name,
                        \'error\' => sprintf(\'Paso "%s" fallo.\', $name),
                    ];
                }
            } catch (Throwable $e) {
                return [
                    \'passed\' => false,
                    \'total_steps\' => $total,
                    \'executed_steps\' => $executed,
                    \'failed_step\' => $name,
                    \'error\' => $e->getMessage(),
                ];
            }
        }

        return [
            \'passed\' => true,
            \'total_steps\' => $total,
            \'executed_steps\' => $executed,
            \'failed_step\' => null,
            \'error\' => null,
        ];
    }

    public function reset(): void
    {
        $this->steps = [];
    }
}
